// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ────────────────────────────────────────────────────────────
   axis shaft (solid)     → CylinderGeometry(r=0.028, L=3)  black MeshBasicMaterial
   arrowhead              → ConeGeometry(0.09, 0.25)        black
   hidden axis half (3D)  → Line + LineDashedMaterial       black, computeLineDistances
   origin dot             → SphereGeometry(0.09)            black
   a) teal point-boundary → BoxGeometry(0.16, 0.7, 0.02)    teal #8CCFC9
   a) half-space tint     → PlaneGeometry(1,0.5) scaled     teal a=0.18
   b) line boundary       → BoxGeometry(4.8, 0.12, 0.02)    teal / terracotta #D2714E
   b) half-plane tint     → clipped-polygon BufferGeometry  neuron colour a=0.18
   c) plane boundary      → Group of 4 quadrant PlaneGeometry quads (painter-safe)
                            gray 5.6×4.6, teal 5.0×5.4, terracotta 6.0×5.0
   c) half-space slab     → BoxGeometry(w,h,2.4) on + side  neuron colour a=0.14
   input point            → SphereGeometry(0.13)            orange-red #FF5722
   drop lines             → Line + LineDashedMaterial       grey
   labels x₁ x₂ x₃ a) b) c) → addLabel, italic serif
────────────────────────────────────────────────────────────────────────────── */

const C = { black: 0x000000, teal: 0x8CCFC9, terra: 0xD2714E, gray: 0xC7CBCC, pt: 0xFF5722 };
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);
const AX_L = 3.0, AX_R = 0.028, TIP = 3.25;

/* ── panel bookkeeping (cross-fade groups) ─────────────────────────────── */
const panels = {};
function makePanel(name) {
  const g = new THREE.Group();
  scene.add(g);
  panels[name] = { group: g, mats: [], labels: [], alpha: name === '1d' ? 1 : 0, target: name === '1d' ? 1 : 0 };
  return g;
}
function collectMats(name) {
  const p = panels[name];
  p.mats.length = 0;
  const seen = new Set();
  p.group.traverse(o => {
    const m = o.material; if (!m) return;
    (Array.isArray(m) ? m : [m]).forEach(mm => {
      if (seen.has(mm)) return; seen.add(mm);
      mm.transparent = true;
      p.mats.push({ m: mm, base: mm.opacity });
    });
  });
}

/* ── primitive builders ────────────────────────────────────────────────── */
function shaft(from, to, mat, r) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r || AX_R, r || AX_R, len, 14), mat);
  m.position.copy(from).add(to).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(V3(0, 1, 0), dir.normalize());
  return m;
}
function head(tip, dir, mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.25, 18), mat);
  m.position.copy(tip).addScaledVector(dir, -0.125);
  m.quaternion.setFromUnitVectors(V3(0, 1, 0), dir.clone().normalize());
  return m;
}
function dashLine(pts, mat) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  l.computeLineDistances();
  return l;
}
function solidHalf(g, dir, mat) {
  g.add(shaft(V3(0, 0, 0), dir.clone().multiplyScalar(AX_L), mat));
  g.add(head(dir.clone().multiplyScalar(TIP), dir, mat));
}
function dashedHalf(g, dir, mat, dmat) {
  g.add(dashLine([V3(0, 0, 0), dir.clone().multiplyScalar(AX_L)], dmat));
  g.add(head(dir.clone().multiplyScalar(TIP), dir, mat));
}
function dot(mat) { return new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 14), mat); }

/* ── PANEL a) 1D ───────────────────────────────────────────────────────── */
const g1 = makePanel('1d');
const blk1 = new THREE.MeshBasicMaterial({ color: C.black, transparent: true });
solidHalf(g1, V3(1, 0, 0), blk1); solidHalf(g1, V3(-1, 0, 0), blk1);
const dot1 = dot(blk1); dot1.position.z = 0.02; g1.add(dot1);
const bar1Mat = new THREE.MeshBasicMaterial({ color: C.teal, transparent: true, opacity: 1 });
const bar1 = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.7, 0.02), bar1Mat);
g1.add(bar1);
const tint1Mat = new THREE.MeshBasicMaterial({ color: C.teal, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false });
const tint1 = new THREE.Mesh(new THREE.PlaneGeometry(1, 0.5), tint1Mat);
tint1.position.z = -0.01; tint1.renderOrder = -1; g1.add(tint1);
collectMats('1d');

/* ── PANEL b) 2D ───────────────────────────────────────────────────────── */
const g2 = makePanel('2d');
const blk2 = new THREE.MeshBasicMaterial({ color: C.black, transparent: true });
solidHalf(g2, V3(1, 0, 0), blk2); solidHalf(g2, V3(-1, 0, 0), blk2);
solidHalf(g2, V3(0, 1, 0), blk2); solidHalf(g2, V3(0, -1, 0), blk2);
function makeLine2(color) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(4.8, 0.12, 0.02), mat);
  g2.add(mesh);
  const tmat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false });
  const tint = new THREE.Mesh(new THREE.BufferGeometry(), tmat);
  tint.position.z = -0.012; tint.renderOrder = -1; g2.add(tint);
  return { mesh, tint };
}
const line2 = { teal: makeLine2(C.teal), terra: makeLine2(C.terra) };
const dot2 = dot(blk2); dot2.position.z = 0.03; g2.add(dot2);
collectMats('2d');

/* ── PANEL c) 3D ───────────────────────────────────────────────────────── */
const g3 = makePanel('3d');
const blk3 = new THREE.MeshBasicMaterial({ color: C.black, transparent: true });
const dsh3 = new THREE.LineDashedMaterial({ color: C.black, dashSize: 0.17, gapSize: 0.12, transparent: true });
solidHalf(g3, V3(1, 0, 0), blk3);   dashedHalf(g3, V3(-1, 0, 0), blk3, dsh3);
solidHalf(g3, V3(0, 1, 0), blk3);   dashedHalf(g3, V3(0, -1, 0), blk3, dsh3);
solidHalf(g3, V3(0, 0, 1), blk3);   dashedHalf(g3, V3(0, 0, -1), blk3, dsh3);
const dot3 = dot(blk3); g3.add(dot3);

function makePlaneGroup(color, halfW, halfH, order) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.75, side: THREE.DoubleSide, depthWrite: false
  });
  const grp = new THREE.Group();
  for (const sx of [-1, 1]) for (const sy of [-1, 1]) {
    const q = new THREE.Mesh(new THREE.PlaneGeometry(halfW, halfH), mat);
    q.position.set(sx * halfW / 2, sy * halfH / 2, 0);
    q.renderOrder = order;
    grp.add(q);
  }
  const smat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.14, side: THREE.DoubleSide, depthWrite: false });
  const slab = new THREE.Mesh(new THREE.BoxGeometry(2 * halfW, 2 * halfH, 2.4), smat);
  slab.position.set(0, 0, 1.2); slab.renderOrder = order + 10;
  grp.add(slab);
  g3.add(grp);
  return { grp, mat, slab };
}
const plane3 = {
  terra: makePlaneGroup(C.terra, 3.0, 2.5, 1),   // x2 = 0 : span(x1,x3)
  gray:  makePlaneGroup(C.gray,  2.8, 2.3, 2),   // x3 = 0 : span(x1,x2)
  teal:  makePlaneGroup(C.teal,  2.5, 2.7, 3)    // x1 = 0 : span(x2,x3)
};
collectMats('3d');

/* ── input point + drop lines (shared across panels) ───────────────────── */
const ptGroup = new THREE.Group(); scene.add(ptGroup);
const ptMat = new THREE.MeshBasicMaterial({ color: C.pt });
const ptMesh = new THREE.Mesh(new THREE.SphereGeometry(0.13, 22, 16), ptMat);
ptGroup.add(ptMesh);
const dropMat = new THREE.LineDashedMaterial({ color: 0x777777, dashSize: 0.11, gapSize: 0.08 });
const dropLines = [0, 1, 2].map(() => {
  const l = dashLine([V3(0, 0, 0), V3(0, 0, 0)], dropMat);
  ptGroup.add(l); return l;
});
registerInteractive(ptMesh, {
  title: 'Input point x',
  tooltip: 'Drag me — each neuron only reports sign(w·x + β)',
  body: 'This is one input vector. Every neuron looks at which side of its own hyperplane the point lies on, i.e. the sign of w·x + β. Drag it across a boundary and that neuron flips its decision.'
});

/* ── state ─────────────────────────────────────────────────────────────── */
const state = {
  panel: '1d',
  neuron: 'teal',
  w1: { teal: 1, terra: 0, gray: 0 },
  beta: 0,
  p: V3(1.4, 0, 0)
};
const NCOL = { teal: '#5aa9a1', terra: '#c0603c', gray: '#7d8486' };
const NNAME = { teal: 'teal', terra: 'terracotta', gray: 'gray' };

function neuronW(id) {
  const w = state.w1[id];
  if (id === 'teal') return V3(w, 0, 0);
  if (id === 'terra') return V3(w, 1, 0);
  return V3(w, 0, 1);
}
function activeNeurons() {
  if (state.panel === '1d') return ['teal'];
  if (state.panel === '2d') return ['teal', 'terra'];
  return ['teal', 'terra', 'gray'];
}

/* ── half-plane polygon clipping (panel b tint) ────────────────────────── */
function clipHalfPlane(poly, nx, ny, dd) {
  const out = [];
  for (let i = 0; i < poly.length; i++) {
    const A = poly[i], B = poly[(i + 1) % poly.length];
    const fa = nx * A[0] + ny * A[1] - dd, fb = nx * B[0] + ny * B[1] - dd;
    if (fa >= 0) out.push(A);
    if ((fa >= 0) !== (fb >= 0)) {
      const t = fa / (fa - fb);
      out.push([A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])]);
    }
  }
  return out;
}
function polyGeom(pts) {
  const pos = [];
  if (pts.length >= 3) {
    for (let i = 1; i < pts.length - 1; i++) {
      pos.push(pts[0][0], pts[0][1], 0, pts[i][0], pts[i][1], 0, pts[i + 1][0], pts[i + 1][1], 0);
    }
  } else { pos.push(0, 0, 0, 0, 0, 0, 0, 0, 0); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return g;
}

/* ── boundary update ───────────────────────────────────────────────────── */
function updateBoundaries() {
  const b = state.beta;

  // a) 1D
  const w1 = state.w1.teal;
  if (Math.abs(w1) > 1e-4) {
    const x0 = Math.max(-2.9, Math.min(2.9, -b / w1));
    bar1.visible = true; bar1.position.set(x0, 0, 0);
    const far = w1 > 0 ? 3.0 : -3.0;
    const len = Math.abs(far - x0);
    tint1.visible = (state.neuron === 'teal');
    tint1.scale.set(Math.max(len, 1e-3), 1, 1);
    tint1.position.x = (x0 + far) / 2;
  } else { bar1.visible = false; tint1.visible = false; }

  // b) 2D
  for (const id of ['teal', 'terra']) {
    const w = neuronW(id); const len = Math.hypot(w.x, w.y);
    const L = line2[id];
    if (len < 1e-4) { L.mesh.visible = false; L.tint.visible = false; continue; }
    const n = V3(w.x / len, w.y / len, 0);
    const t = V3(-n.y, n.x, 0);
    const c = n.clone().multiplyScalar(-b / len);
    L.mesh.visible = true;
    L.mesh.position.copy(c);
    L.mesh.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(t, n, V3(0, 0, 1)));
    const show = (state.neuron === id);
    L.tint.visible = show;
    if (show) {
      const sq = [[-3, -3], [3, -3], [3, 3], [-3, 3]];
      const pts = clipHalfPlane(sq, n.x, n.y, n.x * c.x + n.y * c.y);
      const old = L.tint.geometry;
      L.tint.geometry = polyGeom(pts);
      if (old) old.dispose();
    }
  }

  // c) 3D
  for (const id of ['teal', 'terra', 'gray']) {
    const w = neuronW(id); const len = w.length();
    const P = plane3[id];
    if (len < 1e-4) { P.grp.visible = false; continue; }
    P.grp.visible = true;
    const n = w.clone().multiplyScalar(1 / len);
    P.grp.quaternion.setFromUnitVectors(V3(0, 0, 1), n);
    P.grp.position.copy(n).multiplyScalar(-b / len);
    P.slab.visible = (state.neuron === id);
  }
  updatePoint();
}

/* ── input point ───────────────────────────────────────────────────────── */
function clampPoint() {
  if (state.panel === '1d') { state.p.y = 0; state.p.z = 0; }
  if (state.panel === '2d') { state.p.z = 0; }
  state.p.x = Math.max(-2.6, Math.min(2.6, state.p.x));
  state.p.y = Math.max(-2.6, Math.min(2.6, state.p.y));
  state.p.z = Math.max(-2.6, Math.min(2.6, state.p.z));
}
function updatePoint() {
  clampPoint();
  ptMesh.position.copy(state.p);
  const P = state.p;
  const feet = [V3(P.x, 0, 0), V3(0, P.y, 0), V3(0, 0, P.z)];
  const nAx = state.panel === '1d' ? 0 : state.panel === '2d' ? 2 : 3;
  dropLines.forEach((l, i) => {
    l.visible = i < nAx;
    if (!l.visible) return;
    l.geometry.dispose();
    l.geometry = new THREE.BufferGeometry().setFromPoints([P.clone(), feet[i]]);
    l.computeLineDistances();
  });
  updateHUD();
}
function updateHUD() {
  const hud = document.getElementById('hud');
  const rows = activeNeurons().map(id => {
    const v = neuronW(id).dot(state.p) + state.beta;
    return `<span style="color:${NCOL[id]}">■</span> ${NNAME[id]}: ${v.toFixed(2)} → <b>${v >= 0 ? '+' : '−'}</b>`;
  });
  const code = activeNeurons().map(id => (neuronW(id).dot(state.p) + state.beta) >= 0 ? '1' : '0').join('');
  hud.innerHTML = rows.join('<br>') + `<br>region code = <b>${code}</b>`;
}

/* ── camera / panel switching ──────────────────────────────────────────── */
function applyCamera() {
  if (state.panel === '3d') {
    setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.68 });
  } else {
    setCameraView({ projection: 'orthographic', axisScreenAngles: null, heightFraction: 0.68 });
  }
}
function setNeuron(id, quiet) {
  state.neuron = id;
  document.querySelectorAll('#neuronBtns button').forEach(b => b.classList.toggle('active', b.dataset.v === id));
  syncSliders();
  if (!quiet) updateBoundaries();
}
function setPanel(p) {
  state.panel = p;
  for (const k in panels) panels[k].target = (k === p) ? 1 : 0;
  if (p === '1d' && state.neuron !== 'teal') setNeuron('teal', true);
  if (p === '2d' && state.neuron === 'gray') setNeuron('teal', true);
  document.querySelectorAll('#dimBtns button').forEach(b => b.classList.toggle('active', b.dataset.v === p));
  document.querySelectorAll('#neuronBtns button').forEach(b => {
    const ok = b.dataset.v === 'teal' || (b.dataset.v === 'terra' && p !== '1d') || (b.dataset.v === 'gray' && p === '3d');
    b.disabled = !ok; b.style.opacity = ok ? 1 : 0.4;
  });
  document.getElementById('orbitHint').textContent =
    p === '3d' ? 'Orbit enabled: drag the background to turn the planes.' : 'Orbit is enabled only in panel c).';
  applyCamera();
  updateBoundaries();
}

/* ── sliders & buttons ─────────────────────────────────────────────────── */
const sW = document.getElementById('weightW1');
const sB = document.getElementById('biasOffset');
function syncSliders() {
  sW.value = state.w1[state.neuron];
  sB.value = state.beta;
  document.getElementById('w1v').textContent = Number(state.w1[state.neuron]).toFixed(2);
  document.getElementById('bv').textContent = Number(state.beta).toFixed(2);
}
let tween = null, autoPlay = false, stepIdx = 0, lastStep = performance.now();
function playBtnLabel() { document.getElementById('stepPlay').textContent = autoPlay ? '❚❚ Pause' : '▶ Play'; }

sW.addEventListener('input', () => { tween = null; state.w1[state.neuron] = parseFloat(sW.value); syncSliders(); updateBoundaries(); });
sB.addEventListener('input', () => { tween = null; state.beta = parseFloat(sB.value); syncSliders(); updateBoundaries(); });
document.querySelectorAll('#dimBtns button').forEach(b =>
  b.addEventListener('click', () => { autoPlay = false; playBtnLabel(); tween = null; setPanel(b.dataset.v); }));
document.querySelectorAll('#neuronBtns button').forEach(b =>
  b.addEventListener('click', () => { autoPlay = false; playBtnLabel(); tween = null; setNeuron(b.dataset.v); }));
document.getElementById('btnReset').style.display = '';

/* ── dragging the input point ──────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragging = false, hovering = false;
function ptrFrom(e) {
  const r = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPtr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointermove', e => {
  ptrFrom(e);
  if (dragging) {
    dragRay.setFromCamera(dragPtr, camera);
    if (dragRay.ray.intersectPlane(dragPlane, hitPt)) { state.p.copy(hitPt); updatePoint(); }
    return;
  }
  dragRay.setFromCamera(dragPtr, camera);
  hovering = dragRay.intersectObject(ptMesh, false).length > 0;
  controls.enabled = !hovering;
});
canvas.addEventListener('pointerdown', e => {
  if (!hovering) return;
  dragging = true;
  controls.enabled = false;
  const nrm = new THREE.Vector3();
  camera.getWorldDirection(nrm);
  if (state.panel !== '3d') nrm.set(0, 0, 1);
  dragPlane.setFromNormalAndCoplanarPoint(nrm, state.p);
  if (canvas.setPointerCapture) canvas.setPointerCapture(e.pointerId);
});
window.addEventListener('pointerup', () => { dragging = false; controls.enabled = true; });

/* ── camera (after all geometry) ───────────────────────────────────────── */
applyCamera();

/* ── labels ────────────────────────────────────────────────────────────── */
const LS = { fontSize: '17px' };
const mathX = i => `<i style="font-family:Georgia,'Times New Roman',serif">x</i><sub style="font-family:Georgia,serif">${i}</sub>`;
const letter = t => `<i style="font-family:Georgia,'Times New Roman',serif">${t})</i>`;

panels['1d'].labels.push(addLabel(mathX(1), V3(3.35, -0.35, 0), LS));
panels['1d'].labels.push(addLabel(letter('a'), V3(-3.0, 2.3, 0), { fontSize: '21px' }));

panels['2d'].labels.push(addLabel(mathX(1), V3(3.35, -0.35, 0), LS));
panels['2d'].labels.push(addLabel(mathX(2), V3(0.5, 3.3, 0), LS));
panels['2d'].labels.push(addLabel(letter('b'), V3(-3.0, 2.3, 0), { fontSize: '21px' }));

panels['3d'].labels.push(addLabel(mathX(1), V3(3.35, 0, 0), { fontSize: '17px', offset: [16, 18] }));
panels['3d'].labels.push(addLabel(mathX(2), V3(0, 3.35, 0), { fontSize: '17px', offset: [24, -6] }));
panels['3d'].labels.push(addLabel(mathX(3), V3(0, 0, 3.4), { fontSize: '17px', offset: [-22, 14] }));
panels['3d'].labels.push(addLabel(letter('c'), V3(-3.0, 2.9, 0), { fontSize: '21px' }));

/* ── explainers on the boundaries ──────────────────────────────────────── */
registerInteractive(bar1, {
  title: 'Boundary in 1D is a point',
  tooltip: '1D hyperplane = a single point',
  body: 'With one input, w₁x₁ + β = 0 has a single solution x₁ = −β/w₁. That single point is the "hyperplane": dimension 0 = 1 − 1.'
});
registerInteractive(line2.teal.mesh, {
  title: 'Teal boundary in 2D',
  tooltip: 'A line: w·x + β = 0',
  body: 'In two dimensions the zero set of w₁x₁ + w₂x₂ + β is a straight line — dimension 1 = 2 − 1 — splitting the plane into two half-planes.'
});
registerInteractive(line2.terra.mesh, {
  title: 'Terracotta boundary in 2D',
  tooltip: 'A second neuron, a second line',
  body: 'A second neuron has its own weights and bias, hence its own line. Two lines carve the plane into four regions; the pair of signs identifies the region.'
});
for (const id of ['teal', 'terra', 'gray']) {
  plane3[id].grp.children.forEach(q => {
    if (!q.isMesh) return;
    registerInteractive(q, {
      title: `${NNAME[id]} plane in 3D`,
      tooltip: 'A flat plane: w·x + β = 0',
      body: 'With three inputs the boundary is a whole plane — dimension 2 = 3 − 1. Each plane splits space into a positive and a negative half-space; three planes give up to eight regions.'
    });
  });
}

/* ── demo steps ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'a) One input, a point boundary',
    narration: 'With a single input x₁ the pre-activation w₁x₁ + β vanishes at one point — the teal tick. Everything on the shaded side is the positive half-space.',
    st: { panel: '1d', neuron: 'teal', w1: 1, beta: 0 } },
  { title: 'Bias slides the boundary',
    narration: 'Increasing β moves the zero-crossing along the axis; the sign reported for a fixed input can flip without the weight changing at all.',
    st: { panel: '1d', neuron: 'teal', w1: 1, beta: 0.9 } },
  { title: 'b) Two inputs, line boundaries',
    narration: 'In 2D each neuron\'s boundary is a line through the origin: teal is x₁ = 0, terracotta is x₂ = 0. Each splits the plane into two half-planes.',
    st: { panel: '2d', neuron: 'teal', w1: 1, beta: 0 } },
  { title: 'Tilting with the weight',
    narration: 'Drive w₁ of the terracotta neuron away from 0 and its line pivots about the origin; the shaded positive region rotates with it — weights set orientation.',
    st: { panel: '2d', neuron: 'terra', w1: -1.4, beta: 0 } },
  { title: 'c) Three inputs, plane boundaries',
    narration: 'With three inputs each boundary is a full plane. Orbit the scene and drag the point: the three planes cut space into octant-like regions and the combined signs give the output class.',
    st: { panel: '3d', neuron: 'teal', w1: 1, beta: 0 } }
];
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setPanel(s.st.panel);
  setNeuron(s.st.neuron, true);
  tween = { t: 0, dur: 0.8, w0: state.w1[state.neuron], b0: state.beta, w1: s.st.w1, beta: s.st.beta };
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narration;
  lastStep = performance.now();
}
document.getElementById('stepNext').addEventListener('click', () => { autoPlay = false; playBtnLabel(); goToStep(stepIdx + 1); });
document.getElementById('stepPrev').addEventListener('click', () => { autoPlay = false; playBtnLabel(); goToStep(stepIdx - 1); });
document.getElementById('stepPlay').addEventListener('click', () => { autoPlay = !autoPlay; playBtnLabel(); lastStep = performance.now(); });

/* ── fade + tween loop ─────────────────────────────────────────────────── */
function updateFades(dt) {
  for (const k in panels) {
    const p = panels[k];
    const diff = p.target - p.alpha;
    if (Math.abs(diff) > 1e-3) p.alpha += Math.sign(diff) * Math.min(Math.abs(diff), dt / 0.32);
    else p.alpha = p.target;
    p.group.visible = p.alpha > 0.005;
    for (const e of p.mats) e.m.opacity = e.base * p.alpha;
    for (const L of p.labels) {
      L.div.style.opacity = p.alpha;
      L.div.style.visibility = p.alpha > 0.02 ? 'visible' : 'hidden';
    }
  }
}
let _tPrev = performance.now();
function figTick() {
  requestAnimationFrame(figTick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _tPrev) / 1000); _tPrev = now;
  updateFades(dt);
  if (tween) {
    tween.t += dt / tween.dur;
    const u = Math.min(1, tween.t);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    state.w1[state.neuron] = tween.w0 + (tween.w1 - tween.w0) * e;
    state.beta = tween.b0 + (tween.beta - tween.b0) * e;
    syncSliders(); updateBoundaries();
    if (u >= 1) tween = null;
  }
  controls.enableRotate = (state.panel === '3d') && !dragging && !hovering;
  if (autoPlay && now - lastStep > 5200) goToStep(stepIdx + 1);
}

/* ── boot ──────────────────────────────────────────────────────────────── */
syncSliders();
setPanel('1d');
document.getElementById('stepTitle').textContent = steps[0].title;
document.getElementById('stepNarr').textContent = steps[0].narration;
playBtnLabel();
figTick();
// @FIGURE_CODE_END
